import React, { forwardRef, useId, useImperativeHandle, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, random, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

type AnamorphicFlareProps = {
  /** Lockup revealed behind the streak. Falls back to a placeholder "remocn" lockup. */
  children?: React.ReactNode;
  /** Warm tint of the streak glow and ghosts. */
  tint?: string;
  /** Color of the hot core line. */
  coreColor?: string;
  backgroundColor?: string;
  /** Number of ghost orbs mirrored across the frame center. */
  ghosts?: number;
  /** Vertical position of the streak, 0 to 1. */
  y?: number;
  seed?: number;
  speed?: number;
};

const anamorphicFlareDefaults = {
  tint: "#E5322D",
  coreColor: "#FFFFFF",
  backgroundColor: "#111111",
  ghosts: 4,
  y: 0.5,
  seed: 2,
  speed: 1,
};

const IGNITE = 6;
const CROSS_START = 4;
const CROSS_END = 26;
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

const PLACEHOLDER_FONT =
  "-apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, Helvetica, Arial, sans-serif";

// Neutral lockup shown when no children are passed.
function PlaceholderLockup({
  mark,
  dot,
  text,
  scale = 1,
}: {
  mark: string;
  dot: string;
  text: string;
  scale?: number;
}) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 28 * scale }}>
      <div
        style={{
          width: 120 * scale,
          height: 120 * scale,
          borderRadius: 32 * scale,
          backgroundColor: mark,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: 36 * scale,
            height: 36 * scale,
            borderRadius: "50%",
            backgroundColor: dot,
          }}
        />
      </div>
      <span
        style={{
          fontFamily: PLACEHOLDER_FONT,
          fontSize: 104 * scale,
          fontWeight: 800,
          letterSpacing: "-0.04em",
          color: text,
        }}
      >
        remocn
      </span>
    </div>
  );
}

function AnamorphicFlareBase(props: AnamorphicFlareProps) {
  const { children, tint, coreColor, backgroundColor, ghosts, y, seed, speed } =
    { ...anamorphicFlareDefaults, ...props };
  const uid = `anamorphic-flare-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const t = frame * Math.max(0, speed);
  const cy = y * height;
  const cx = width / 2;

  const head = interpolate(t, [CROSS_START, CROSS_END], [0.07, 1.12], {
    ...clamp,
    easing: Easing.bezier(0.45, 0, 0.4, 1),
  });
  const hx = head * width;
  const ignite = interpolate(t, [0, IGNITE], [0, 1], {
    ...clamp,
    easing: Easing.out(Easing.cubic),
  });
  const fade = interpolate(t, [CROSS_END - 6, CROSS_END + 2], [1, 0], clamp);
  const power = ignite * fade;
  const streakLen =
    width *
    interpolate(t, [0, 12], [0.04, 1.3], {
      ...clamp,
      easing: Easing.out(Easing.quad),
    });
  const coreH = Math.max(2, height * 0.004);
  const glowH = height * 0.05;
  const residual = interpolate(
    t,
    [CROSS_END - 2, CROSS_END + 14],
    [0, 0.14],
    clamp,
  );
  const soft = width * 0.08;
  const mask = `linear-gradient(90deg, #000 0px, #000 ${hx - soft}px, transparent ${hx}px)`;

  const ghostList = Array.from(
    { length: Math.max(0, Math.round(ghosts)) },
    (_, i) => {
      const k = -1.3 + random(`anamorphic-flare-${seed}-${i}-k`) * 2.2;
      return {
        x: cx - (hx - cx) * k,
        r: height * (0.025 + 0.07 * random(`anamorphic-flare-${seed}-${i}-r`)),
        o: 0.12 + 0.18 * random(`anamorphic-flare-${seed}-${i}-o`),
        dy: (random(`anamorphic-flare-${seed}-${i}-y`) - 0.5) * height * 0.05,
      };
    },
  );

  return (
    <AbsoluteFill style={{ backgroundColor }}>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", inset: 0 }}
      >
        <defs>
          <linearGradient id={`${uid}-trail`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor={tint} stopOpacity={0} />
            <stop offset="0.5" stopColor={tint} stopOpacity={1} />
            <stop offset="1" stopColor={tint} stopOpacity={0} />
          </linearGradient>
        </defs>
        <rect
          x={0}
          y={cy - 1}
          width={width}
          height={2}
          fill={`url(#${uid}-trail)`}
          opacity={residual}
        />
      </svg>
      <AbsoluteFill
        style={{
          alignItems: "center",
          justifyContent: "center",
          WebkitMaskImage: mask,
          maskImage: mask,
        }}
      >
        {children ?? (
          <PlaceholderLockup
            mark={tint}
            dot={backgroundColor}
            text={coreColor}
          />
        )}
      </AbsoluteFill>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{
          position: "absolute",
          inset: 0,
          mixBlendMode: "screen",
        }}
      >
        <defs>
          <linearGradient id={`${uid}-core`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor={coreColor} stopOpacity={0} />
            <stop offset="0.5" stopColor={coreColor} stopOpacity={1} />
            <stop offset="1" stopColor={coreColor} stopOpacity={0} />
          </linearGradient>
          <radialGradient id={`${uid}-bloom`}>
            <stop offset="0" stopColor={coreColor} stopOpacity={1} />
            <stop offset="0.25" stopColor={tint} stopOpacity={0.7} />
            <stop offset="1" stopColor={tint} stopOpacity={0} />
          </radialGradient>
          <radialGradient id={`${uid}-ghost`}>
            <stop offset="0" stopColor={tint} stopOpacity={0.15} />
            <stop offset="0.8" stopColor={tint} stopOpacity={0.5} />
            <stop offset="1" stopColor={tint} stopOpacity={0} />
          </radialGradient>
          <filter
            id={`${uid}-blur`}
            x={-width}
            y={-height}
            width={width * 3}
            height={height * 3}
            filterUnits="userSpaceOnUse"
          >
            <feGaussianBlur stdDeviation={glowH * 0.35} />
          </filter>
        </defs>
        <g opacity={power}>
          <rect
            x={hx - streakLen * 0.45}
            y={cy - glowH / 2}
            width={streakLen * 0.9}
            height={glowH}
            fill={`url(#${uid}-trail)`}
            opacity={0.55}
            filter={`url(#${uid}-blur)`}
          />
          <rect
            x={hx - streakLen / 2}
            y={cy - coreH / 2}
            width={streakLen}
            height={coreH}
            fill={`url(#${uid}-core)`}
          />
          <ellipse
            cx={hx}
            cy={cy}
            rx={height * 0.16}
            ry={height * 0.1}
            fill={`url(#${uid}-bloom)`}
          />
          {ghostList.map((g, i) => (
            <circle
              key={i}
              cx={g.x}
              cy={cy + g.dy}
              r={g.r}
              fill={`url(#${uid}-ghost)`}
              opacity={g.o * 2}
            />
          ))}
        </g>
      </svg>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  ghosts: {
    type: "number",
    default: 4,
    min: 0,
    max: 8,
    step: 1,
    description: "Ghosts",
    hiddenFromList: false,
  },
  y: {
    type: "number",
    default: 0.5,
    min: 0.1,
    max: 0.9,
    step: 0.01,
    description: "Streak height",
    hiddenFromList: false,
  },
  seed: {
    type: "number",
    default: 2,
    min: 1,
    max: 99,
    step: 1,
    description: "Seed",
    hiddenFromList: false,
  },
  tint: {
    type: "color",
    default: "#E5322D",
    description: "Tint",
  },
  coreColor: {
    type: "color",
    default: "#FFFFFF",
    description: "Core",
  },
  backgroundColor: {
    type: "color",
    default: "#111111",
    description: "Background",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["ghosts","y","seed","tint","coreColor","backgroundColor","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  ghosts: 4,
  y: 0.5,
  seed: 2,
  tint: "#E5322D",
  coreColor: "#FFFFFF",
  backgroundColor: "#111111",
  speed: 1,
};

type AnamorphicFlareElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof AnamorphicFlareBase>;

const AnamorphicFlareInner = forwardRef<
  HTMLDivElement,
  AnamorphicFlareElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<AnamorphicFlare>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <AnamorphicFlareBase
          {...(componentProps as unknown as ComponentProps<typeof AnamorphicFlareBase>)}
        />
      </div>
    </Sequence>
  );
});

export const AnamorphicFlare = Interactive.withSchema({
  Component: AnamorphicFlareInner,
  componentName: "<AnamorphicFlare>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
